#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;

#define INF 10000

struct E {
    int a, b, c;
    E(int a, int b, int c) : a(a), b(b), c(c) {}
};

#define MONEY 0
#define EKI 1

int main() {
    int n, m;
    while (cin >> n >> m) {
        if (n == 0 && m == 0) break;

        vector<vector<int>> costs(n + 1, vector<int>(n + 1, INF));
        vector<vector<int>> times(n + 1, vector<int>(n + 1, INF));
        vector<E> cs, ts;
        int a, b, c, t;
        for (int i = 0; i < n; ++i) {
            cin >> a >> b >> c >> t;
            costs[a][b] = c; costs[b][a] = c;
            times[a][b] = t; times[b][a] = t;
            cs.emplace_back(a, b, c);
            cs.emplace_back(b, a, c);
            ts.emplace_back(a, b, t);
            ts.emplace_back(b, a, t);
        }
        for (int i = 0; i < m; ++i) {
            costs[i][i] = 0;
            times[i][i] = 0;
        }
        int k, p, q, r;
        cin >> k;
        for (int i = 0; i < k; ++i) {
            vector<int> d(n + 1, INF);
            cin >> p >> q >> r;
            d[p] = 0;
            while (true) {
                bool update = false;
                for (const auto& edge : (r == MONEY ? cs : ts)) {
                    if (d[edge.a] != INF && d[edge.b] > d[edge.a] + edge.c) {
                        d[edge.b] = d[edge.a] + edge.c;
                        update = true;
                    }
                }
                if (!update) break;
            }
            cout << d[q] << endl;
        }
    }
    return 0;
}

