#include <vector>
#include <cstring>
#include <algorithm>
#include <queue>
using namespace std;

const int INF = 10000;

struct E {
    int b, c;
    E(int b, int c) : b(b), c(c) {}
};

#define MONEY 0
#define EKI 1

int main() {
    int n, m;
    while (cin >> n >> m) {
        if (n == 0 && m == 0) break;
        vector<vector<pair<int, int>>> costs(n + 1);
        vector<vector<pair<int, int>>> times(n + 1);
        int a, b, c, t;
        for (int i = 0; i < n; ++i) {
            cin >> a >> b >> c >> t;
            costs[a].emplace_back(b, c);
            costs[b].emplace_back(a, c);
            times[a].emplace_back(b, t);
            times[b].emplace_back(a, t);
        }
        for (int i = 0; i <= n; ++i) {
            costs[i].emplace_back(i, 0);
            times[i].emplace_back(i, 0);
        }
        int k, p, q, r;
        cin >> k;
        for (int i = 0; i < k; ++i) {
            vector<int> d(n + 1, INF);
            cin >> p >> q >> r;
            d[p] = 0;
            priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
            pq.push({0, p});
            while (!pq.empty()) {
                auto [dist, node] = pq.top();
                pq.pop();
                if (dist > d[node]) continue; // Skip if we already found a better path
                auto& edges = (r == MONEY ? costs : times);
                for (const auto& edge : edges[node]) {
                    if (d[edge.first] > dist + edge.second) {
                        d[edge.first] = dist + edge.second;
                        pq.push({d[edge.first], edge.first});
                    }
                }
            }
            cout << d[q] << endl;
        }
    }
    return 0;
}

